        // 专门用于根据提供的数据刷新UI的函数
        function refreshWithData(data) {
            var mapData = processJsonData(data);
            if (!mapData) {
                document.getElementById('map-title').textContent = "数据加载错误";
                return;
            }
            mapData.locations = adjustLayoutForOverlaps(mapData.locations);
            var pLoc = mapData.locations.find(function(l) { return l.name === mapData.protagonistLocationName; });
            mapData.currentUserPosition = pLoc ? { x: pLoc.x + pLoc.width / 2, y: pLoc.y + pLoc.height / 2 } : { x: 400, y: 300 };
            renderMapInterface(mapData);

            // Restore Important Characters Bar
            var charContainer = document.getElementById('important-character-buttons');
            var charSection = document.getElementById('current-important-characters');
            charContainer.innerHTML = '';
            var hasNpcs = false;
