                if (c.isProtagonist) {
                    protagonistChar = c;
                    return;
                }
                var isAway = String(c.isAway || '').trim().toLowerCase();
                if (c.name && isAway !== '是' && isAway !== 'true') {
                    hasNpcs = true;
                    var btn = document.createElement('button');
                    btn.className = 'partner-button';
